include '../config/menu.php'; $where=es_admin()?'t.eliminado=0':'t.eliminado=0 AND t.id_cuidadora_usuario='.uid(); $rows=$pdo->query("SELECT t.*,u.nombre usuario FROM turnos t JOIN usuarios u ON t.id_cuidadora_usuario=u.id_usuario WHERE $where ORDER BY fecha_hora DESC")->fetchAll(); ?>
